"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[70285],{70285:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/d2131f9266ef4653d1c8655a04236639.jpg\\"\\n  title=\\"Little League\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"Container 1,String Bean Alley Queen Victoria Market 513 Elizabeth St North, Melbourne VIC 3000 Australia\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nWe arrived early at Victoria Market and stopped by the cafe in <mark>String Bean Alley</mark> near the entrance to enjoy a quiet moment before the market opened.  \\nOrdered a <mark>Long Black</mark> to go, sat outside for a bit, and soaked in the morning calm.  \\n\\nThe taste wasn\'t anything special, but it was a reminder that Australian coffee is reliably above average no matter where you go.  \\n\\n```adcard\\n```\\n\\n`League of Honest Coffee` team runs this place, using `Padre` beans.  \\n\\nIt was the perfect little pit stop before exploring the market.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/d2131f9266ef4653d1c8655a04236639.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/8e150861904daf6dbae45b1db53f897c.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/9410e3984408ab27b36613c0e905fa38.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/2975de3265510fded7074847bf68681f.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n<img src=\\"/assets/snippets/location/672677db8e030369240051c44a138d69.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little League\\">\\n</pictures>\\n"}')}}]);